mountedZeroToFive:
(async()=>{
 const fixture=JSON.parse(sessionStorage.getItem('community-1-fixture'));
 const {poll,brand}=fixture;
 const beforeTotal=document.querySelector('.community-poll .community-share > span')?.textContent;
 if(beforeTotal!=='0 respuestas')throw new Error('fixture must be mounted at 0: '+beforeTotal);
 for(let i=0;i<5;i++){const r=await fetch('/api/community/'+poll.token+'/responses',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({segmentId:poll.groups[0].id,optionId:poll.options[i<3?0:1].id})});if(!r.ok)throw new Error('public synthetic response '+r.status)}
 const button=[...document.querySelectorAll('button')].find(x=>x.textContent.trim()==='Actualizar');if(!button)throw new Error('Actualizar missing');button.click();
 await new Promise(r=>setTimeout(r,600));
 const [polls,signals]=await Promise.all([fetch('/api/brands/'+brand.id+'/community-polls').then(x=>x.json()),fetch('/api/brands/'+brand.id+'/audience-signals').then(x=>x.json())]);
 const sensor=document.querySelector('.community-sensor').innerText;
 const signalText=document.querySelector('.journey-signal-list')?.innerText||'';
 const result={test:'mounted-zero-to-five-and-update',pass:sensor.includes('5 respuestas')&&sensor.includes('3 de 5')&&sensor.includes('2 de 5')&&signalText.includes('3 respuestas de 5')&&signalText.includes('2 respuestas de 5'),question:poll.question,beforeTotal,apiTotal:polls.polls.find(x=>x.id===poll.id).totalResponses,apiSignals:signals.signals.filter(x=>x.communityPollId===poll.id).map(x=>({id:x.id,note:x.note})),sensorText:sensor,signalText};
 console.log(JSON.stringify(result));return result;
})()
